import '../../features/privacy/domain/privacy_checklist.dart';

/// Arabic privacy guidance mapped to canonical stable practice IDs.
class ArabicPrivacyContent {
  ArabicPrivacyContent._();
  static const Map<String, Map<String, String>> _data = {
    'account-unique-passwords': {'title':'استخدم كلمات مرور فريدة للحسابات المهمة','why':'قد يؤدي إعادة استخدام كلمة المرور إلى تعريض حساباتك الأخرى للخطر إذا تسرّبت من خدمة واحدة.','action':'استخدم مدير كلمات مرور موثوقاً لإنشاء كلمة مرور طويلة ومختلفة لكل حساب مهم. احمِ المدير بكلمة مرور رئيسية واضبط وسائل الاسترداد المتاحة.','limit':'لن يحمي مدير كلمات المرور الحساب إذا اختُرقت كلمة المرور الرئيسية أو وسيلة الاسترداد.'},
    'account-mfa': {'title':'فعّل المصادقة متعددة العوامل','why':'تقلل وسيلة تحقق إضافية من أثر سرقة كلمة المرور.','action':'فعّل المصادقة متعددة العوامل للبريد والحسابات المالية والسحابية والاجتماعية. استخدم مفاتيح المرور أو مفاتيح الأمان المادية متى أمكن، واحمِ النسخ الاحتياطية لتطبيق المصادقة.','limit':'تختلف وسائل المصادقة متعددة العوامل في مستوى الحماية. وقد تتعرض رموز SMS لهجمات تبديل شريحة SIM أو نقل الرقم.'},
    'account-recovery': {'title':'راجع وسائل استرداد الحسابات','why':'قد يمنع عنوان بريد أو رقم استرداد قديم استعادة الوصول بصورة مشروعة، أو يسهّل الاستيلاء على الحساب.','action':'راجع عناوين البريد الاحتياطية وأرقام الهواتف ورموز الاسترداد والأجهزة الموثوقة ضمن إعدادات الأمان الرسمية لكل خدمة.','limit':'تختلف إعدادات الاسترداد حسب الخدمة. لا يستطيع ORVIKA التحقق من أن مزوّد الخدمة طبّق تغييراتك.'},
    'device-updates': {'title':'حدّث أنظمة التشغيل والتطبيقات','why':'تعالج التحديثات غالباً ثغرات قد يستغلها المهاجمون إن بقيت دون إصلاح.','action':'فعّل تحديثات الأمان التلقائية متى أمكن. ثبّت التحديثات عبر آلية الجهاز المدمجة أو متجر التطبيقات الرسمي.','limit':'تقلل التحديثات المخاطر المعروفة، لكنها لا تضمن خلو الجهاز من الاختراق.'},
    'device-lock': {'title':'احمِ جهازك بقفل شاشة قوي','why':'قد يكشف الجهاز المفقود أو المتروك مفتوحاً الرسائل والحسابات والبيانات المحفوظة.','action':'استخدم رمز PIN أو كلمة مرور طويلة، واضبط مهلة قصيرة للقفل التلقائي. ويمكن استخدام القياسات الحيوية كوسيلة إضافية مريحة لفتح القفل.','limit':'تختلف القياسات الحيوية وإعدادات القفل حسب الجهاز. ولا يعني قفل الشاشة بالضرورة تشفير كل النسخ الاحتياطية الخارجية.'},
    'device-backups': {'title':'راجع النسخ الاحتياطية وخدمة العثور على الجهاز','why':'تساعد النسخ الاحتياطية على الاستعادة، بينما تساعد ميزات العثور على الجهاز في تحديد موقع الجهاز المفقود أو حمايته عن بُعد.','action':'تحقّق من البيانات التي تُنسخ احتياطياً، ومن يمكنه الوصول إلى حساب النسخ الاحتياطي، وما إذا كان تشفير النسخ متاحاً، وما إذا كانت ميزتا العثور على الجهاز والقفل عن بُعد مفعّلتين.','limit':'يعتمد التوفر والتشفير على نظام التشغيل ومزوّد الخدمة. راجع الوثائق الرسمية الحالية.'},
    'apps-permissions': {'title':'راجع أذونات التطبيقات','why':'قد تحتفظ التطبيقات بإمكانية الوصول إلى الموقع وجهات الاتصال والكاميرا والميكروفون والصور والأجهزة القريبة بما يتجاوز حاجتها.','action':'افتح إعدادات الخصوصية أو الأذونات في النظام. ألغِ الأذونات غير الضرورية واسمح بالوصول المؤقت أو أثناء الاستخدام متى توفر.','limit':'قد تحتاج بعض الميزات إلى أذونات محددة. قد يؤدي إلغاء الإذن إلى تعطيل جزء من التطبيق.'},
    'apps-unused': {'title':'أزل التطبيقات التي لم تعد تستخدمها','why':'قد تتوقف التطبيقات غير المستخدمة عن تلقي التحديثات، أو تحتفظ ببيانات وأذونات لم تعد تحتاج إليها.','action':'راجع قائمة التطبيقات المثبتة واحذف ما لا تحتاج إليه. قبل الحذف، تحقّق من إمكانية تصدير البيانات أو إلغاء الاشتراك أو حذف الحساب المرتبط.','limit':'قد يؤدي حذف التطبيق وحده إلى عدم حذف الحساب أو البيانات التي يحتفظ بها مزوّد الخدمة.'},
    'apps-sources': {'title':'ثبّت التطبيقات من مصادر موثوقة','why':'قد تحتوي التطبيقات على تعليمات برمجية غير مرغوبة أو تطلب وصولاً أوسع من اللازم.','action':'استخدم المتاجر الرسمية أو قناة توزيع موثوقة من المطوّر. تحقّق من هوية المطوّر والأذونات المطلوبة وسجل التحديثات قبل التثبيت.','limit':'وجود التطبيق في متجر رسمي لا يضمن سلامته أو احترامه للخصوصية.'},
    'browsing-tracking': {'title':'راجع إعدادات خصوصية المتصفح والتتبع','why':'قد تكشف ملفات تعريف الارتباط وأذونات المواقع والتتبع بين المواقع عادات التصفح الخاصة بك.','action':'راجع الحماية من التتبع وملفات تعريف الارتباط التابعة لجهات خارجية وأذونات المواقع المحفوظة والإضافات. أزل الإضافات غير المعروفة أو غير الضرورية.','limit':'قد يؤدي حظر أدوات التتبع إلى تعطيل بعض المواقع، ولا يجعل التصفح مجهول الهوية.'},
    'browsing-sharing': {'title':'قلّل مشاركة المعلومات الشخصية','why':'قد تُستخدم المنشورات العامة ومعلومات الملف الشخصي لانتحال هويتك أو استهدافك بالاحتيال أو مهاجمة إجراءات استرداد حسابك.','action':'راجع حقول الملف الشخصي العامة وجمهور المنشورات ومشاركة الموقع والمنشورات القديمة. لا تنشر المستندات أو خطط السفر أو تلميحات استرداد الحساب.','limit':'قد يُنسخ المحتوى أو يُؤرشف قبل تغيير إعدادات الخصوصية.'},
    'browsing-network': {'title':'استخدم اتصالات موثوقة وراجع نشاط الشبكة','why':'قد تكشف بوابات Wi-Fi المزيفة والاتصالات غير الآمنة نشاطك أو تعيد توجيهك إلى صفحات مضللة.','action':'فضّل الشبكات الموثوقة، وتحقق من اسم الشبكة لدى مالكها، وتجنب العمليات الحساسة على الشبكات المجهولة، واستخدم HTTPS. عطّل الاتصال التلقائي بنقاط الوصول غير المعروفة.','limit':'يحمي HTTPS البيانات أثناء نقلها إلى الموقع، لكنه لا يثبت أصالة الموقع ولا يجعل الشبكة المجهولة آمنة.'},
  };
  static PrivacyPractice localize(PrivacyPractice item, String code) {
    if (code != 'ar') return item;
    final value = _data[item.id];
    if (value == null) return item;
    return PrivacyPractice(
      id: item.id,
      title: value['title']!,
      category: item.category,
      why: value['why']!,
      action: value['action']!,
      limit: value['limit']!,
    );
  }
}
